      "text": {
        "en": {
          "name": "Olga",
          "backgroundName": "Dark Elf Queen",
          "backgroundDescription": "A dark elf queen bearing a crescent staff. She weakens enemies with curses and commands the battlefield with black flame and eclipses.",
          "traitName": "Dark Queen",
          "traitDescription": "Olga’s identity and growth are preserved through durable records.",
          "traitTooltip": [
            "Curses, dark sorcery and soul enslavement."
          ]
        },
        "zh": {
          "name": "奥利卡",
          "backgroundName": "黑暗精灵女王",
          "backgroundDescription": "手持月牙权杖的黑暗精灵女王。以诅咒削弱敌人，以黑炎和月蚀统御战场。",
          "traitName": "黑暗女王",
          "traitDescription": "奥利卡的身份与成长由持久化记录维护。",
          "traitTooltip": [
            "诅咒、黑暗法术与灵魂支配。"
          ]
        }
      },
